export function normalizeLanguage(value) {
  return SUPPORTED_LANGUAGES.includes(value) ? value : 'en';
}

export function t(lang, key) {
  const current = messages[normalizeLanguage(lang)] || messages.en;
  return current[key] ?? messages.en[key] ?? key;
}

export function applyTranslations(lang, scope = document) {
  const current = normalizeLanguage(lang);
  scope.querySelectorAll('[data-i18n]').forEach(node => {
    node.textContent = t(current, node.dataset.i18n);
  });
  scope.querySelectorAll('[data-i18n-placeholder]').forEach(node => {
    node.placeholder = t(current, node.dataset.i18nPlaceholder);
  });
  scope.querySelectorAll('[data-i18n-title]').forEach(node => {
    node.title = t(current, node.dataset.i18nTitle);
  });
  scope.querySelectorAll('[data-i18n-aria-label]').forEach(node => {
    node.setAttribute('aria-label', t(current, node.dataset.i18nAriaLabel));
  });
}
